CREATE TRIGGER json_git_acquisitions_roots_manifest_insert BEFORE INSERT ON git_acquisitions
WHEN NEW.roots_manifest IS NOT NULL AND CASE WHEN NOT json_valid(NEW.roots_manifest) THEN 1 WHEN json_type(NEW.roots_manifest)<>'array' THEN 1 ELSE (
 EXISTS(SELECT 1 FROM json_tree(NEW.roots_manifest) j WHERE typeof(j.key)='text' GROUP BY j.parent,j.key HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM json_each(NEW.roots_manifest) m WHERE CASE WHEN m.type<>'object' THEN 1 ELSE (m.type<>'object' OR EXISTS(SELECT 1 FROM json_each(m.value) k WHERE k.key NOT IN ('name','name_b64','oid','type','peeled','role','number','expected')) OR coalesce(json_type(m.value,'$.name'),'')<>'text' OR length(json_extract(m.value,'$.name'))=0 OR instr(json_extract(m.value,'$.name'),char(0))>0 OR coalesce(json_type(m.value,'$.name_b64'),'')<>'text' OR length(json_extract(m.value,'$.name_b64'))=0 OR instr(json_extract(m.value,'$.name_b64'),char(0))>0 OR coalesce(json_type(m.value,'$.oid'),'')<>'text' OR length(json_extract(m.value,'$.oid'))=0 OR instr(json_extract(m.value,'$.oid'),char(0))>0 OR coalesce(json_type(m.value,'$.type'),'')<>'text' OR length(json_extract(m.value,'$.type'))=0 OR instr(json_extract(m.value,'$.type'),char(0))>0 OR coalesce(json_type(m.value,'$.peeled'),'') NOT IN ('null','text') OR json_extract(m.value,'$.type') NOT IN ('commit','tree','blob','tag') OR NOT (typeof(json_extract(m.value,'$.oid'))='text' AND length(json_extract(m.value,'$.oid'))=(CASE NEW.object_format WHEN 'sha1' THEN 40 WHEN 'sha256' THEN 64 ELSE -1 END) AND length(CAST(json_extract(m.value,'$.oid') AS BLOB))=(CASE NEW.object_format WHEN 'sha1' THEN 40 WHEN 'sha256' THEN 64 ELSE -1 END) AND json_extract(m.value,'$.oid') NOT GLOB '*[^0-9a-f]*') OR (json_type(m.value,'$.peeled')='text' AND NOT (typeof(json_extract(m.value,'$.peeled'))='text' AND length(json_extract(m.value,'$.peeled'))=(CASE NEW.object_format WHEN 'sha1' THEN 40 WHEN 'sha256' THEN 64 ELSE -1 END) AND length(CAST(json_extract(m.value,'$.peeled') AS BLOB))=(CASE NEW.object_format WHEN 'sha1' THEN 40 WHEN 'sha256' THEN 64 ELSE -1 END) AND json_extract(m.value,'$.peeled') NOT GLOB '*[^0-9a-f]*')) OR length(json_extract(m.value,'$.name_b64'))%4<>0 OR json_extract(m.value,'$.name_b64') GLOB '*[^A-Za-z0-9+/=]*' OR length(rtrim(json_extract(m.value,'$.name_b64'),'='))<length(json_extract(m.value,'$.name_b64'))-2 OR instr(rtrim(json_extract(m.value,'$.name_b64'),'='),'=')>0 OR ((json_type(m.value,'$.role') IS NOT NULL OR json_type(m.value,'$.number') IS NOT NULL OR json_type(m.value,'$.expected') IS NOT NULL) AND (coalesce(json_type(m.value,'$.role'),'')<>'text' OR length(json_extract(m.value,'$.role'))=0 OR instr(json_extract(m.value,'$.role'),char(0))>0 OR coalesce(json_type(m.value,'$.number'),'')<>'integer' OR json_extract(m.value,'$.number')<=0 OR coalesce(json_type(m.value,'$.expected'),'')<>'text' OR json_extract(m.value,'$.expected')<>json_extract(m.value,'$.oid')))) END)
 OR EXISTS(SELECT 1 FROM json_tree(NEW.roots_manifest) j WHERE j.key IN ('acquisition_root_id','change_request_observation_id','code_observation_id','completion_marker_id','content_id','document_observation_id','fetch_occurrence_id','git_object_id','source_id','text_body_id') OR ((j.key GLOB '*_uuidv4' OR j.key GLOB '*_uuidv4s' OR j.key GLOB '*_sha256' OR j.key IN ('sha256','representation','references')) AND j.key NOT IN ('change_request_id','change_request_ids','change_request_observation_uuidv4','code_observation_uuidv4','completion_marker_uuidv4','completion_marker_uuidv4s','document_observation_uuidv4','fetch_collection_id','fetch_collection_ids','fetch_occurrence_uuidv4','fetch_occurrence_uuidv4s','git_acquisition_id','git_acquisition_ids','parent_fetch_collection_id','parsed_result_uuidv4','parsed_result_uuidv4s','parser_profile_uuidv4','parser_profile_verification_uuidv4','relation_uuidv4','repository_binding_id','repository_endpoint_id','repository_uuidv4','resume_scope_id','selection_decision_uuidv4','selection_predecessors','service_instance_uuidv4','source_input_uuidv4','source_registration_uuidv4','stable_scope') AND NOT EXISTS(SELECT 1 FROM json_tree(NEW.roots_manifest) p WHERE p.id=j.parent AND p.key='payload')))
 OR EXISTS(SELECT 1 FROM json_tree(NEW.roots_manifest) j WHERE j.key='change_request_id' AND (j.type<>'text' OR NOT (length(j.value)>0 AND instr(j.value,char(0))=0)))
