CREATE TRIGGER json_parser_profiles_definition_json_insert BEFORE INSERT ON parser_profiles
WHEN NEW.definition_json IS NOT NULL AND CASE WHEN NOT json_valid(NEW.definition_json) THEN 1 WHEN json_type(NEW.definition_json)<>'object' THEN 1 ELSE (
 EXISTS(SELECT 1 FROM json_tree(NEW.definition_json) j WHERE typeof(j.key)='text' GROUP BY j.parent,j.key HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM json_tree(NEW.definition_json) j WHERE j.key IN ('acquisition_root_id','change_request_observation_id','code_observation_id','completion_marker_id','content_id','document_observation_id','fetch_occurrence_id','git_object_id','source_id','text_body_id') OR ((j.key GLOB '*_uuidv4' OR j.key GLOB '*_uuidv4s' OR j.key GLOB '*_sha256' OR j.key IN ('sha256','representation','references')) AND j.key NOT IN ('change_request_id','change_request_ids','change_request_observation_uuidv4','code_observation_uuidv4','completion_marker_uuidv4','completion_marker_uuidv4s','document_observation_uuidv4','fetch_collection_id','fetch_collection_ids','fetch_occurrence_uuidv4','fetch_occurrence_uuidv4s','git_acquisition_id','git_acquisition_ids','parent_fetch_collection_id','parsed_result_uuidv4','parsed_result_uuidv4s','parser_profile_uuidv4','parser_profile_verification_uuidv4','relation_uuidv4','repository_binding_id','repository_endpoint_id','repository_uuidv4','resume_scope_id','selection_decision_uuidv4','selection_predecessors','service_instance_uuidv4','source_input_uuidv4','source_registration_uuidv4','stable_scope') AND j.key<>'sha256' AND j.key NOT GLOB '*_sha256' AND NOT EXISTS(SELECT 1 FROM json_tree(NEW.definition_json) p WHERE p.id=j.parent AND p.key='payload')))
 OR EXISTS(SELECT 1 FROM json_tree(NEW.definition_json) j WHERE (j.key='sha256' OR j.key GLOB '*_sha256') AND NOT EXISTS(SELECT 1 FROM json_tree(NEW.definition_json) p WHERE p.id=j.parent AND p.key='payload') AND (j.type<>'text' OR NOT (typeof(j.value)='text' AND length(j.value)=(64) AND length(CAST(j.value AS BLOB))=(64) AND j.value NOT GLOB '*[^0-9a-f]*')))
 OR EXISTS(SELECT 1 FROM json_tree(NEW.definition_json) j WHERE j.key='change_request_id' AND (j.type<>'text' OR NOT (length(j.value)>0 AND instr(j.value,char(0))=0)))
 OR EXISTS(SELECT 1 FROM json_tree(NEW.definition_json) j WHERE j.key='change_request_id' AND NOT EXISTS(SELECT 1 FROM change_requests t WHERE t.change_request_id=j.value AND (NULL IS NULL OR t.repository_uuidv4 IS NULL OR NULL=t.repository_uuidv4) AND (NULL IS NULL OR NULL IS NULL OR NULL=NULL) AND (NULL IS NULL OR t.repository_uuidv4 IS NULL OR EXISTS(SELECT 1 FROM source_repositories m JOIN sources s USING(source_id) WHERE m.repository_uuidv4=t.repository_uuidv4 AND s.source_registration_uuidv4=NULL))))
