CREATE TRIGGER json_resume_scopes_request_context_update BEFORE UPDATE ON resume_scopes
WHEN NEW.request_context IS NOT NULL AND CASE WHEN NOT json_valid(NEW.request_context) THEN 1 WHEN json_type(NEW.request_context)<>'object' THEN 1 ELSE (
 EXISTS(SELECT 1 FROM json_tree(json_remove(NEW.request_context,'$.head','$.base')) j WHERE typeof(j.key)='text' GROUP BY j.parent,j.key HAVING count(*)>1)
 OR (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.thread') IS NOT NULL AND (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.thread')<>'text' OR length(json_extract(json_remove(NEW.request_context,'$.head','$.base'),'$.thread'))=0))
 OR (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.review_thread_provider_resource_id') IS NOT NULL AND (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.review_thread_provider_resource_id')<>'text' OR length(json_extract(json_remove(NEW.request_context,'$.head','$.base'),'$.review_thread_provider_resource_id'))=0))
 OR (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.query') IS NOT NULL AND (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.query')<>'text' OR length(json_extract(json_remove(NEW.request_context,'$.head','$.base'),'$.query'))=0))
 OR (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.url') IS NOT NULL AND (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.url')<>'text' OR length(json_extract(json_remove(NEW.request_context,'$.head','$.base'),'$.url'))=0))
 OR (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.method') IS NOT NULL AND (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.method')<>'text' OR length(json_extract(json_remove(NEW.request_context,'$.head','$.base'),'$.method'))=0))
 OR (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.variables') IS NOT NULL AND json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.variables')<>'object')
 OR (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.variables.thread') IS NOT NULL AND (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.variables.thread')<>'text' OR length(json_extract(json_remove(NEW.request_context,'$.head','$.base'),'$.variables.thread'))=0))
 OR (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.variables.owner') IS NOT NULL AND (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.variables.owner')<>'text' OR length(json_extract(json_remove(NEW.request_context,'$.head','$.base'),'$.variables.owner'))=0))
 OR (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.variables.name') IS NOT NULL AND (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.variables.name')<>'text' OR length(json_extract(json_remove(NEW.request_context,'$.head','$.base'),'$.variables.name'))=0))
 OR (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.variables.cursor') IS NOT NULL AND json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.variables.cursor') NOT IN ('text','null'))
 OR (json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.variables.commentCursor') IS NOT NULL AND json_type(json_remove(NEW.request_context,'$.head','$.base'),'$.variables.commentCursor') NOT IN ('text','null'))
